mapper.select:
SELECT m.id AS member_id, m.name, m.phone, COALESCE((SELECT mp.name FROM member_memberships mm JOIN membership_products mp ON mp.id = mm.product_id WHERE mm.member_id = m.id AND mm.status = 'ACTIVE' AND mm.end_date >= CURRENT_DATE ORDER BY mm.end_date LIMIT 1), '활성 회원권 없음') AS active_membership, (SELECT MAX(a.checked_in_at) FROM attendances a WHERE a.member_id = m.id) AS last_attendance_at, (SELECT MAX(ws.started_at) FROM workout_sessions ws WHERE ws.member_id = m.id) AS last_workout_at FROM trainers t JOIN trainer_assignments ta ON ta.trainer_id = t.id AND ta.status = 'ACTIVE' JOIN members m ON m.id = ta.member_id AND m.status = 'ACTIVE' WHERE t.user_id = #{userId}
AND (m.name LIKE CONCAT('%', #{keyword}, '%') OR m.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.name

SELECT attendance_date, checked_in_at, checked_out_at
FROM attendances WHERE member_id = #{memberId}
ORDER BY checked_in_at DESC LIMIT 20
